//! `contracts/fixtures/decisions.json` against [`astrid_rules::decisions`].
//!
//! The fixture is generated by running astrid-web's `lib/comment-formats.ts` over a fixed case set
//! (`astrid-web scripts/contract-fixtures/drivers/decisions.mjs`), so what it records is literally
//! what the web reads. Every case is read here and compared, which is what the fixture was copied in
//! for: it arrived in `8fbab12` and had no reader at all until task efae6297.
//!
//! The two option sets the reply cases are answered against are the driver's, and the second one is
//! built here from the same text it builds it from — a reply that picks by letter has to be checked
//! against lettered options, and `4` must find no fourth option.

mod common;

use astrid_rules::decisions::{
    chosen_number, column_letter, parse, rating_style, read_grid, reply, row_name, DecisionOption,
};
use serde_json::Value;

const FIXTURE: &str = include_str!("../../../contracts/fixtures/decisions.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("the fixture parses")
}

/// The driver's lettered set: `parseDecision('**Decision:** x\n\n- **A.** a\n- **B.** b\n- **C.** c')`.
const LETTERED_TEXT: &str = "**Decision:** x\n\n- **A.** a\n- **B.** b\n- **C.** c";

fn options(value: &Value) -> Vec<DecisionOption> {
    value
        .as_array()
        .expect("options are an array")
        .iter()
        .map(|option| DecisionOption {
            letter: option["letter"].as_str().unwrap().to_string(),
            number: option["number"].as_u64().unwrap() as u32,
            text: option["text"].as_str().unwrap().to_string(),
            recommended: option["recommended"].as_bool().unwrap(),
        })
        .collect()
}

#[test]
fn every_rating_token_means_what_web_says_it_means() {
    let fixture = fixture();
    let ratings = fixture["ratings"]
        .as_object()
        .expect("ratings are an object");
    assert_eq!(ratings.len(), 8, "the fixture lists every token");
    for (token, expected) in ratings {
        let style = rating_style(token).unwrap_or_else(|| panic!("{token} is a rating"));
        assert_eq!(
            serde_json::to_value(style).unwrap(),
            *expected,
            "{token} reads differently here than on web"
        );
    }
    assert!(rating_style("?").is_none(), "anything else is not a rating");
}

#[test]
fn every_text_reads_as_a_decision_exactly_as_web_reads_it() {
    let fixture = fixture();
    let cases = fixture["decisions"].as_array().unwrap();
    assert!(cases.len() >= 12, "the fixture still holds every case");
    let failures: Vec<String> = cases
        .iter()
        .filter_map(|case| {
            let text = case["text"].as_str().unwrap();
            let ours = serde_json::to_value(parse(text)).unwrap();
            (ours != case["parsed"]).then(|| {
                format!(
                    "{} ({})\n   web:  {}\n   core: {ours}",
                    case["name"], case["note"], case["parsed"]
                )
            })
        })
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn a_card_posts_the_reply_web_posts() {
    let fixture = fixture();
    let canonical = options(&fixture["decisions"][0]["parsed"]["options"]);
    let ours: Vec<String> = canonical.iter().map(reply).collect();
    let expected: Vec<String> = fixture["replyFormat"]
        .as_array()
        .unwrap()
        .iter()
        .map(|line| line.as_str().unwrap().to_string())
        .collect();
    assert_eq!(ours, expected);
}

#[test]
fn an_option_with_no_text_replies_with_its_number_alone() {
    let option = DecisionOption {
        letter: "A".to_string(),
        number: 2,
        text: String::new(),
        recommended: false,
    };
    assert_eq!(reply(&option), "2");
}

#[test]
fn every_reply_picks_the_option_web_picks() {
    let fixture = fixture();
    let numbered = options(&fixture["decisions"][0]["parsed"]["options"]);
    let lettered = parse(LETTERED_TEXT)
        .expect("the lettered set parses")
        .options;
    assert_eq!(lettered.len(), 3, "A, B and C, so `4` finds no option");

    let cases = fixture["replies"].as_array().unwrap();
    assert!(cases.len() >= 18);
    let failures: Vec<String> = cases
        .iter()
        .filter_map(|case| {
            let text = case["reply"].as_str().unwrap();
            let ours = (
                serde_json::to_value(chosen_number(text, &numbered)).unwrap(),
                serde_json::to_value(chosen_number(text, &lettered)).unwrap(),
            );
            (ours.0 != case["chosenNumbered"] || ours.1 != case["chosenLettered"]).then(|| {
                format!(
                    "{text:?}\n   web:  numbered {} lettered {}\n   core: numbered {} lettered {}",
                    case["chosenNumbered"], case["chosenLettered"], ours.0, ours.1
                )
            })
        })
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn every_table_reads_as_a_grid_exactly_as_web_reads_it() {
    let fixture = fixture();
    let cases = fixture["grids"].as_array().unwrap();
    assert!(cases.len() >= 5);
    let failures: Vec<String> = cases
        .iter()
        .filter_map(|case| {
            let rows: Vec<Vec<String>> = case["rows"]
                .as_array()
                .unwrap()
                .iter()
                .map(|row| {
                    row.as_array()
                        .unwrap()
                        .iter()
                        .map(|cell| cell.as_str().unwrap().to_string())
                        .collect()
                })
                .collect();
            let ours = serde_json::to_value(read_grid(&rows)).unwrap();
            let expected = serde_json::json!({
                "isGrid": case["isGrid"],
                "cells": case["cells"],
                "rowNames": case["rowNames"],
            });
            (ours != expected).then(|| {
                format!(
                    "{} ({})\n   web:  {expected}\n   core: {ours}",
                    case["name"], case["note"]
                )
            })
        })
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn a_row_loses_the_marker_its_writer_put_in_front() {
    let fixture = fixture();
    let cases = fixture["rowMarkers"].as_array().unwrap();
    assert!(cases.len() >= 8);
    for case in cases {
        let text = case["text"].as_str().unwrap();
        assert_eq!(
            row_name(text),
            case["name"].as_str().unwrap(),
            "row_name({text:?})"
        );
    }
}

#[test]
fn a_criterion_column_is_lettered_as_a_spreadsheet_letters_it() {
    let fixture = fixture();
    let cases = fixture["columnLetters"].as_array().unwrap();
    assert!(cases.len() >= 9);
    for case in cases {
        let index = case["index"].as_u64().unwrap() as u32;
        assert_eq!(
            column_letter(index),
            case["letter"].as_str().unwrap(),
            "column_letter({index})"
        );
    }
}
